def _retry_wait(r: Response, now: Callable[[], datetime]) -> float:
    default = 1.0 if r.status == 429 else 2.0
    value = None
    for k, v in r.headers.items():
        if k.lower() == "retry-after":
            value = v.strip()
    if not value:
        return default
    if value.isdigit():
        return float(int(value))
    try:
        dt = parsedate_to_datetime(value)
    except (TypeError, ValueError):
        return default
    if dt is None:
        return default
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return max(0.0, (dt - now()).total_seconds())


def _request(transport, path, params, sleep, now) -> Response:
    for attempt in range(4):
        r = transport(path, dict(params))
        if r.status == 200:
            return r
        if r.status in (429, 503) and attempt < 3:
            wait = _retry_wait(r, now)
            if wait > 0:
                sleep(wait)
            continue
        try:
            code = json.loads(r.body)["error"]["code"]
        except Exception:
            code = ""
        raise ApiError(r.status, code)
